    #[test]
    fn capture_feedback_skips_delivery_when_non_interactive() {
        let temp = TempDir::new().unwrap();
        let store = create_test_store(&temp);
        let mut ui = MockUI::new();
        // MockUI defaults to non-interactive

        let result =
