        store.update(&entry).unwrap();

        let validator = CacheValidator::new(&store);
        let result = validator
            .validate("http:test", "template", RemoteCacheStrategy::Etag)
            .unwrap();

        assert_eq!(result, ValidationResult::NeedsRevalidation);
    }

